#!/usr/bin/env python3
"""Builds the Blender cheat sheet into the app.

Run after editing Docs/Blender-Cheat-Sheet.md:
    python3 scripts/sync-blender-reference.py
It rewrites Sources/EthersPrismCore/Core/BlenderReferenceText.swift. A test checks the two match.
"""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
text = (root / "Docs/Blender-Cheat-Sheet.md").read_text(encoding="utf-8")
assert '"""###' not in text, "the cheat sheet can't contain the Swift string delimiter"
swift = (
    "// Generated by scripts/sync-blender-reference.py from Docs/Blender-Cheat-Sheet.md. Don't edit by hand.\n\n"
    "extension BlenderReference {\n"
    "    /// The full Blender cheat sheet (Markdown).\n"
    '    public static let text = ###"""\n'
    + text.rstrip("\n") + "\n"
    + '"""###\n'
    "}\n"
)
(root / "Sources/EthersPrismCore/Core/BlenderReferenceText.swift").write_text(swift, encoding="utf-8")
print("Updated BlenderReferenceText.swift")
